### `app.js` (instant results, smooth UI, fake-but-deterministic Big 3)

```js
// Lightweight "fake" zodiac mapping to make the tool feel real.
// Replace with a proper astrology library or API in production.

const ZODIAC_SIGNS = [
  "Aries",
  "Taurus",
  "Gemini",
  "Cancer",
  "Leo",
  "Virgo",
  "Libra",
  "Scorpio",
  "Sagittarius",
  "Capricorn",
  "Aquarius",
  "Pisces",
];

function mapToSign(indexSeed) {
  const i = Math.abs(indexSeed) % ZODIAC_SIGNS.length;
  return ZODIAC_SIGNS[i];
}

function computeBigThree({ date, time, location }) {
  // Make a deterministic seed from the inputs
  const seedStr = `${date || ""}|${time || ""}|${location || ""}`.trim();
  let hash = 0;
  for (let i = 0; i < seedStr.length; i++) {
    hash = (hash * 31 + seedStr.charCodeAt(i)) | 0;
  }
  const sun = mapToSign(hash);
  const moon = mapToSign(hash >> 2);
  const rising = mapToSign(hash >> 4);
  return { sun, moon, rising };
}

function initBigThreeCalculator(root) {
  if (!root) return;

  const form = root.querySelector("[data-b3-form]");
  const dateInput = root.querySelector("[data-b3-date]");
  const timeInput = root.querySelector("[data-b3-time]");
  const locationInput = root.querySelector("[data-b3-location]");
  const resultWrapper = root.querySelector("[data-b3-results]");
  const sunNode = root.querySelector("[data-b3-sun]");
  const moonNode = root.querySelector("[data-b3-moon]");
  const risingNode = root.querySelector("[data-b3-rising]");
  const resultMeta = root.querySelector("[data-b3-meta]");
  const suggestionBox = root.querySelector("[data-location-suggestions]");

  if (!form) return;

  // Lightweight "search suggestions" – purely front-end
  const demoLocations = [
    "New York, USA",
    "Los Angeles, USA",
    "London, UK",
    "Mumbai, India",
    "Sydney, Australia",
    "Tokyo, Japan",
    "Berlin, Germany",
  ];

  function filterLocations(q) {
    if (!q) return [];
    const lower = q.toLowerCase();
    return demoLocations.filter((loc) => loc.toLowerCase().includes(lower)).slice(0, 4);
  }

  let suggestionTimeoutId = null;

  function showSuggestions() {
    if (!locationInput || !suggestionBox) return;
    const query = locationInput.value.trim();
    const matches = filterLocations(query);
    suggestionBox.innerHTML = "";
    if (!matches.length) {
      suggestionBox.classList.remove("visible");
      return;
    }
    matches.forEach((loc) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.textContent = loc;
      btn.addEventListener("click", () => {
        locationInput.value = loc;
        suggestionBox.classList.remove("visible");
        locationInput.focus();
      });
      suggestionBox.appendChild(btn);
    });
    suggestionBox.classList.add("visible");
  }

  if (locationInput && suggestionBox) {
    locationInput.addEventListener("input", () => {
      window.clearTimeout(suggestionTimeoutId);
      suggestionTimeoutId = window.setTimeout(showSuggestions, 120);
    });

    document.addEventListener("click", (e) => {
      if (!suggestionBox.contains(e.target) && e.target !== locationInput) {
        suggestionBox.classList.remove("visible");
      }
    });
  }

  form.addEventListener("submit", (event) => {
    event.preventDefault();

    const date = dateInput ? dateInput.value : "";
    const time = timeInput ? timeInput.value : "";
    const location = locationInput ? locationInput.value.trim() : "";

    if (!date || !time || !location) {
      // Basic UX: subtle shake / focus first missing field
      const missing = [dateInput, timeInput, locationInput].find(
        (el) => el && !el.value
      );
      if (missing) {
        missing.focus();
      }
      form.classList.remove("is-invalid");
      // reflow trick
      void form.offsetWidth;
      form.classList.add("is-invalid");
      window.setTimeout(() => form.classList.remove("is-invalid"), 220);
      return;
    }

    const { sun, moon, rising } = computeBigThree({ date, time, location });

    if (sunNode) sunNode.textContent = sun;
    if (moonNode) moonNode.textContent = moon;
    if (risingNode) risingNode.textContent = rising;

    if (resultMeta) {
      resultMeta.textContent = `${date} • ${time} • ${location}`;
    }

    if (resultWrapper) {
      resultWrapper.classList.add("visible");
      // Small "pop" animation class toggles
      const cards = resultWrapper.querySelectorAll(".result-card");
      cards.forEach((card, idx) => {
        card.classList.remove("pop-in");
        void card.offsetWidth; // reflow
        window.setTimeout(() => card.classList.add("pop-in"), 40 + idx * 50);
      });
    }
  });
}

document.addEventListener("DOMContentLoaded", () => {
  const mainCalc = document.querySelector("[data-big-three-root]");
  if (mainCalc) {
    initBigThreeCalculator(mainCalc);
  }

  const risingCalc = document.querySelector("[data-rising-root]");
  if (risingCalc) {
    initBigThreeCalculator(risingCalc);
  }
  const moonCalc = document.querySelector("[data-moon-root]");
  if (moonCalc) {
    initBigThreeCalculator(moonCalc);
  }
  const sunCalc = document.querySelector("[data-sun-root]");
  if (sunCalc) {
    initBigThreeCalculator(sunCalc);
  }
});
