# ---------- app.js ----------
@'
const SIGNS=["Aries","Taurus","Gemini","Cancer","Leo","Virgo","Libra","Scorpio","Sagittarius","Capricorn","Aquarius","Pisces"];
const sign=(n)=>SIGNS[Math.abs(n)%12];

function calc(date,time,loc){
  const s=`${date}|${time}|${loc}`;
  let h=0;
  for(let i=0;i<s.length;i++) h=((h<<5)-h+s.charCodeAt(i))|0;
  return {sun:sign(h),moon:sign(h>>2),rising:sign(h>>4)};
}

function wireCalculator(root){
  if(!root) return;
  const form=root.querySelector("form");
  const date=root.querySelector("[name=dob]");
  const time=root.querySelector("[name=tob]");
  const loc=root.querySelector("[name=loc]");
  const out=root.querySelector(".results");
  const sun=root.querySelector("[data-sun]");
  const moon=root.querySelector("[data-moon]");
  const rising=root.querySelector("[data-rising]");

  form?.addEventListener("submit",(e)=>{
    e.preventDefault();
    if(!date.value || !time.value || !loc.value.trim()){ alert("Please fill all fields."); return; }
    const r=calc(date.value,time.value,loc.value.trim());
    if(sun) sun.textContent=r.sun;
    if(moon) moon.textContent=r.moon;
    if(rising) rising.textContent=r.rising;
    out?.classList.add("show");
  });
}

document.addEventListener("DOMContentLoaded",()=>{
  wireCalculator(document.querySelector("[data-calc-root]"));
  document.querySelectorAll("[data-year]").forEach(el=>el.textContent=new Date().getFullYear());
});
